function smallestNumber(n, t) {
  let candidate = n;
  while (true) {
    let product = 1;
    let rest = candidate;
    while (rest > 0) {
      product *= rest % 10;
      rest = Math.floor(rest / 10);
    }
    if (product % t === 0) {
      return candidate;
    }
    candidate++;
  }
}

brute:
function smallestNumber(n, t) {
  // List every number up to 200 whose digit product (read from its decimal string) is divisible by t,
  // then take the smallest one that is at least n. Since 100 has the digit product 0, one always exists.
  const good = [];
  for (let x = 1; x <= 200; x++) {
    const product = [...String(x)].reduce((p, digit) => p * Number(digit), 1);
    if (product % t === 0) good.push(x);
  }
  return Math.min(...good.filter(x => x >= n));
}

