function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  // The limits are tiny; large inputs favour the long searches near 100 with awkward divisors.
  if (size === 'large') return [int(80, 100), int(5, 10)];
  return [int(1, 100), int(1, 10)];
}
